(()=>{'use strict';if(window.__OBRIX_OBRAS_AJUSTES_3010)return;window.__OBRIX_OBRAS_AJUSTES_3010=true;
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLowerCase();
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function obraPorId(id){return (window.obras||[]).find(o=>String(o.id)===String(id))}
function abrirObra(id){if(!id)return;if(typeof window.abrir==='function')window.abrir('obras');setTimeout(()=>{const b=document.querySelector(`#listaObras [data-abrir="${CSS.escape(String(id))}"]`);if(b)b.click();else window.OBRIX_OBRAS_FIEL?.abrir?.(id)},120)}
function inicio(){const root=document.getElementById('inicio');if(!root)return;root.querySelectorAll('[data-obra-id],[data-id]').forEach(card=>{const id=card.dataset.obraId||card.dataset.id;if(!obraPorId(id)||card.dataset.obrixAbreObra)return;card.dataset.obrixAbreObra='1';card.style.cursor='pointer';card.addEventListener('click',e=>{if(e.target.closest('button,a,input,select,textarea'))return;abrirObra(id)})})}
function categoria(x){return norm(x.categoria||x.category||x.descricao_categoria||'outras')}
function despesas(id){const obra=obraPorId(id),lista=(window.financeiro||[]).filter(x=>(!x.status_lancamento||x.status_lancamento==='ativo')&&x.tipo==='despesa'&&String(x.obra_id)===String(id));const grupos={mao:{nome:'Mão de obra',total:0,itens:[]},mat:{nome:'Materiais',total:0,itens:[]},comb:{nome:'Combustível',total:0,itens:[]},out:{nome:'Outras despesas',total:0,itens:[]}};lista.forEach(x=>{const c=categoria(x);const g=c.includes('mao')||c.includes('mão')?grupos.mao:c.includes('material')?grupos.mat:c.includes('combust')?grupos.comb:grupos.out;g.total+=Number(x.valor||0);g.itens.push(x)});document.querySelector('.obxDespBack')?.remove();const back=document.createElement('div');back.className='modalBack obxDespBack';back.innerHTML=`<div class="modal obxDespModal"><div class="obxDespHead"><div><h2>Despesas da obra</h2><p>${esc(obra?.nome||'Obra')}</p></div><button type="button" data-fechar>×</button></div><div class="obxDespTotal"><small>Total de despesas</small><b>${money(lista.reduce((s,x)=>s+Number(x.valor||0),0))}</b></div>${Object.values(grupos).map(g=>`<section><div class="obxDespGrupo"><b>${g.nome}</b><strong>${money(g.total)}</strong></div>${g.itens.length?g.itens.map(x=>`<div class="obxDespItem"><div><b>${esc(x.descricao||x.nome||g.nome)}</b><small>${esc(x.data||'')} ${x.observacao?'• '+esc(x.observacao):''}</small></div><strong>${money(x.valor)}</strong></div>`).join(''):'<div class="obxDespVazio">Nenhuma despesa nesta categoria.</div>'}</section>`).join('')}</div>`;document.body.appendChild(back);back.querySelector('[data-fechar]').onclick=()=>back.remove();back.onclick=e=>{if(e.target===back)back.remove()}}
function obras(){const root=document.getElementById('obras');if(!root)return;const hero=root.querySelector(':scope>.hero');if(hero)hero.style.display='none';const head=root.querySelector(':scope>.sectionHead');if(head){head.style.setProperty('display','block','important');head.style.setProperty('width','100%','important');head.querySelectorAll('strong').forEach(x=>x.remove());let b=head.querySelector('button');if(b){b.textContent='+ Nova obra';b.style.setProperty('width','100%','important');b.style.setProperty('display','block','important')}}const filtros=root.querySelector('.obxFiltros');if(filtros)filtros.classList.add('obxFiltros4');root.querySelectorAll('.obxAcao').forEach(b=>{const t=norm(b.textContent);if(t.includes('equipe / dias')||t.includes('equipe/dias')||t.includes('diario de obra')||t.includes('documentos'))b.remove();if(t.includes('despesas da obra')){const card=b.closest('.obxDetalhe');const id=card?.querySelector('[data-obra-id]')?.dataset.obraId||document.querySelector('#listaObras .obxObraCard[data-id]')?.dataset.id;b.onclick=e=>{e.preventDefault();const atual=(window.obras||[]).find(o=>String(o.nome||'')===String(card?.querySelector('h2')?.textContent||''));despesas(atual?.id||id)}}});const det=root.querySelector('.obxDetalhe');if(det&&!det.querySelector('.obxMaoAcaoNovo')){const h=det.querySelector('h2')?.textContent,obra=(window.obras||[]).find(o=>String(o.nome||'')===String(h||'')),acoes=det.querySelector('.obxAcoes');if(obra&&acoes){const b=document.createElement('button');b.className='obxAcao azul obxMaoAcaoNovo';b.innerHTML='<span class="obxIcone">👷</span><span><b>Mão de obra</b><small>Diárias e custos da equipe</small></span><i>›</i>';b.onclick=()=>window.OBRIX_OBRAS_MAO_TESTE?.abrir?.(obra.id);acoes.prepend(b)}}}
const css=document.createElement('style');css.textContent=`#obras .obxFiltros4{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:5px!important;overflow:visible!important;width:100%!important}#obras .obxFiltros4 button{min-width:0!important;width:100%!important;padding:9px 3px!important;font-size:11px!important;white-space:normal!important;line-height:1.05!important}#obras>.sectionHead button{width:100%!important} .obxDespBack{position:fixed;inset:0;z-index:11000;background:rgba(0,0,0,.62);display:flex;align-items:flex-end;justify-content:center;padding:10px}.obxDespModal{width:min(680px,100%);max-height:90vh;overflow:auto;border-radius:18px;background:var(--ob-surface,#fff);color:var(--ob-text,#111);padding:16px}.obxDespHead{display:flex;justify-content:space-between;gap:10px}.obxDespHead h2{margin:0}.obxDespHead p{margin:3px 0 12px;color:var(--ob-muted)}.obxDespHead button{border:0;background:transparent;color:inherit;font-size:28px}.obxDespTotal,.obxDespGrupo,.obxDespItem{display:flex;justify-content:space-between;gap:12px}.obxDespTotal{padding:12px;border:1px solid var(--ob-border);border-radius:11px;margin-bottom:12px}.obxDespTotal small{display:block}.obxDespTotal b{color:#ef4444}.obxDespGrupo{padding:11px 2px;border-bottom:1px solid var(--ob-border)}.obxDespGrupo strong{color:#ef4444}.obxDespItem{padding:10px 2px;border-bottom:1px solid var(--ob-border)}.obxDespItem small{display:block;color:var(--ob-muted);margin-top:3px}.obxDespVazio{padding:10px 2px;color:var(--ob-muted);font-size:13px}@media(min-width:700px){.obxDespBack{align-items:center}}`;
document.head.appendChild(css);let q=false;function run(){q=false;inicio();obras()}function ag(){if(q)return;q=true;requestAnimationFrame(run)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(ag,300),{once:true});else setTimeout(ag,300);new MutationObserver(ag).observe(document.getElementById('app')||document.body,{childList:true,subtree:true});window.addEventListener('pageshow',ag);window.addEventListener('obrix:modules-ready',ag);window.OBRIX_OBRAS_AJUSTES_3010={refresh:ag,despesas,abrirObra};})();

(()=>{'use strict';
if(window.__OBRIX_OBRAS_SYNC_MOBILE_0211)return;window.__OBRIX_OBRAS_SYNC_MOBILE_0211=true;
const style=document.createElement('style');style.id='obrix-obras-sync-mobile-0211-style';style.textContent=`
#obras .obxStatus.andamento{color:#fff!important;-webkit-text-fill-color:#fff!important}
@media(max-width:520px){
  #fmFiltrosPanel .fmFiltrosGrid label:has(#fmFiltroDataInicio),#fmFiltrosPanel .fmFiltrosGrid label:has(#fmFiltroDataFim){grid-column:1/-1!important;min-width:0!important;max-width:100%!important;overflow:visible!important}
  #fmFiltroDataInicio,#fmFiltroDataFim{display:block!important;width:100%!important;max-width:100%!important;min-width:0!important;inline-size:100%!important;box-sizing:border-box!important;font-size:16px!important;padding-left:10px!important;padding-right:10px!important;min-height:46px!important}
}
`;document.head.appendChild(style);

let progressoBusy=false,progressoTimer=null,geralTimer=null,canal=null,reconectarTimer=null,ultimaGeral=0,ultimaProgresso=0,empresaAtual='';
const appAberto=()=>{const app=document.getElementById('app'),login=document.getElementById('login');return !!(app&&!app.classList.contains('hidden')&&(!login||login.classList.contains('hidden')))};
async function contexto(){const p=await window.OBRIX_BACKEND?.profile?.();if(!p?.empresa_id)throw new Error('Perfil indisponível');return{sb:await window.OBRIX_BACKEND.init(),eid:p.empresa_id}}
function aplicarProgresso(rows){const grupos=new Map();(rows||[]).forEach(x=>{if(!x.obra_id)return;const k=String(x.obra_id),g=grupos.get(k)||{s:0,n:0};g.s+=Math.max(0,Math.min(100,Number(x.progresso||0)));g.n++;grupos.set(k,g)});let mudou=false;(window.obras||[]).forEach(o=>{const s=String(o.status||'').toLowerCase(),g=grupos.get(String(o.id));let p=null;if(s==='concluida'||s==='concluída')p=100;else if(g?.n)p=Math.round((g.s/g.n)*10)/10;if(p===null)return;if(Number(o.progresso)!==p||Number(o.percentual)!==p||Number(o.percentual_conclusao)!==p){o.progresso=p;o.percentual=p;o.percentual_conclusao=p;mudou=true}});if(mudou||document.getElementById('obras')&&!document.getElementById('obras').classList.contains('hidden')){try{window.OBRIX_OBRAS_FIEL?.refresh?.()}catch(_){}}return mudou}
async function sincronizarProgresso(forcar=false){if(progressoBusy||!navigator.onLine||!appAberto())return false;if(!forcar&&Date.now()-ultimaProgresso<700)return false;progressoBusy=true;try{const {sb,eid}=await contexto(),r=await sb.from('checklist_itens').select('obra_id,progresso').eq('empresa_id',eid);if(r.error)throw r.error;aplicarProgresso(r.data||[]);ultimaProgresso=Date.now();return true}catch(e){console.warn('OBRIX: progresso das obras será sincronizado depois',e);return false}finally{progressoBusy=false}}
function agendarProgresso(ms=120,forcar=true){clearTimeout(progressoTimer);progressoTimer=setTimeout(()=>sincronizarProgresso(forcar),ms)}
async function atualizarGeral(){if(!navigator.onLine||!appAberto())return false;ultimaGeral=Date.now();try{if(typeof window.OBRIX_REFRESH_ALL==='function')await window.OBRIX_REFRESH_ALL();else if(typeof window.carregar==='function')await window.carregar()}catch(e){console.warn('OBRIX: sincronização geral será repetida depois',e)}finally{agendarProgresso(80,true)}return true}
function agendarGeral(ms=220){clearTimeout(geralTimer);const espera=Math.max(ms,Math.max(0,900-(Date.now()-ultimaGeral)));geralTimer=setTimeout(atualizarGeral,espera)}
function desligarCanal(){clearTimeout(reconectarTimer);reconectarTimer=null;if(canal){try{canal.unsubscribe?.()}catch(_){}canal=null}}
async function conectarRealtime(){if(canal||!navigator.onLine||!appAberto())return false;try{const {sb,eid}=await contexto();empresaAtual=String(eid);let c=sb.channel('obrix-sync-geral-'+empresaAtual);['obras','financeiro','checklist_itens','funcionarios','servicos_extras','diarias','vales','bonus_extras'].forEach(tabela=>{c=c.on('postgres_changes',{event:'*',schema:'public',table:tabela,filter:`empresa_id=eq.${eid}`},()=>{if(tabela==='checklist_itens')agendarProgresso(100,true);agendarGeral(180)})});canal=c.subscribe(status=>{if(status==='SUBSCRIBED'){agendarProgresso(80,true);return}if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED'){desligarCanal();reconectarTimer=setTimeout(conectarRealtime,1400)}});return true}catch(e){console.warn('OBRIX: realtime geral indisponível no momento',e);desligarCanal();reconectarTimer=setTimeout(conectarRealtime,1800);return false}}
function sincronizarAoVoltar(){if(!navigator.onLine||!appAberto())return;if(Date.now()-ultimaGeral>5000)agendarGeral(80);else agendarProgresso(80,true);conectarRealtime()}
document.addEventListener('change',e=>{if(e.target.closest?.('[data-check-range]')){agendarProgresso(180,true);agendarGeral(650)}},true);
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b)return;const t=(b.textContent||'').trim();if(t==='Obras'||b.dataset?.page==='obras')agendarProgresso(80,true)},true);
window.addEventListener('obrix-dados-atualizados',()=>agendarProgresso(60,true));
window.addEventListener('focus',sincronizarAoVoltar);window.addEventListener('pageshow',sincronizarAoVoltar);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')sincronizarAoVoltar()});window.addEventListener('online',()=>{desligarCanal();agendarGeral(80);setTimeout(conectarRealtime,120)});window.addEventListener('offline',desligarCanal);
const app=document.getElementById('app');if(app)new MutationObserver(()=>{if(appAberto()){agendarProgresso(100,true);conectarRealtime()}else desligarCanal()}).observe(app,{attributes:true,attributeFilter:['class']});
setTimeout(()=>{if(appAberto()){agendarProgresso(80,true);conectarRealtime()}},450);setTimeout(()=>{if(appAberto())sincronizarAoVoltar()},1600);
window.OBRIX_SYNC_GERAL={refresh:atualizarGeral,progresso:()=>sincronizarProgresso(true),realtime:conectarRealtime};
})();